rep('packages/database/src/models/task.ts','  private async lockDependencyGraph(): Promise<void> {','  async lockDependencyGraph(): Promise<void> {')
old='''    const [interrupted] = await this.db\n      .select({ id: taskTopics.id })\n      .from(taskTopics)\n      .where(\n        and(\n          eq(taskTopics.taskId, input.id),\n          eq(taskTopics.topicId, input.topicId),\n          input.operationId === null\n            ? isNull(taskTopics.operationId)\n            : eq(taskTopics.operationId, input.operationId),\n          inArray(taskTopics.status, ['running', 'canceled']),\n          this.topicsOwnership(),\n        ),\n      )\n      .for('update');\n    if (!interrupted) return false;\n    await new TaskTopicModel(this.db, this.userId, this.workspaceId).cancelIfRunning(\n      input.id,\n      input.topicId,\n    );\n    // A stopped historical/non-current topic must never inherit the task's\n    // current reservation. Only the exact current topic generation may park\n    // task-level state; otherwise recovery is topic-local.\n    const [taskState] = await this.db\n      .select({\n        currentTopicId: tasks.currentTopicId,\n        runReservationId: tasks.runReservationId,\n        status: tasks.status,\n      })\n      .from(tasks)\n      .where(and(eq(tasks.id, input.id), this.ownership()))\n      .for('update');\n    if (!taskState || !shouldParkInterruptedTask(taskState, input)) return false;'''
new='''    // Lock and validate task generation before mutating its topic. A successor\n    // may reuse the same topic between interruption and compensation; checking\n    // the topic first could cancel that successor before the reservation fence\n    // notices it. Lock order is graph -> task -> topic everywhere.\n    const [taskState] = await this.db\n      .select({\n        currentTopicId: tasks.currentTopicId,\n        runReservationId: tasks.runReservationId,\n        status: tasks.status,\n      })\n      .from(tasks)\n      .where(and(eq(tasks.id, input.id), this.ownership()))\n      .for('update');\n    if (!taskState) return false;\n    const parksTask = shouldParkInterruptedTask(taskState, input);\n    if (input.currentTopicId !== null && !parksTask) return false;\n    if (input.currentTopicId === null && taskState.currentTopicId === input.topicId) return false;\n\n    const [interrupted] = await this.db\n      .select({ id: taskTopics.id })\n      .from(taskTopics)\n      .where(\n        and(\n          eq(taskTopics.taskId, input.id),\n          eq(taskTopics.topicId, input.topicId),\n          input.operationId === null\n            ? isNull(taskTopics.operationId)\n            : eq(taskTopics.operationId, input.operationId),\n          inArray(taskTopics.status, ['running', 'canceled']),\n          this.topicsOwnership(),\n        ),\n      )\n      .for('update');\n    if (!interrupted) return false;\n    await new TaskTopicModel(this.db, this.userId, this.workspaceId).cancelIfRunning(\n      input.id,\n      input.topicId,\n    );\n    if (!parksTask) return false;'''
rep('packages/database/src/models/task.ts',old,new)
rep('apps/server/src/services/task/index.ts','''        const taskModel = new TaskModel(tx, this.userId, this.workspaceId);\n        const taskTopicModel = new TaskTopicModel(tx, this.userId, this.workspaceId);\n\n        // Cancel by the frozen id set rather than the pre-read topic list, so a\n        // topic that started between the snapshot and this transaction is still\n        // closed together with the status update.\n        canceledTopics = await taskTopicModel.cancelRunningByTaskIds(targetIds);''','''        const taskModel = new TaskModel(tx, this.userId, this.workspaceId);\n        const taskTopicModel = new TaskTopicModel(tx, this.userId, this.workspaceId);\n\n        // Establish the graph lock before touching topic rows. Recovery also\n        // starts with this advisory lock, so concurrent cascade/recovery paths\n        // cannot form a topic-row <-> graph-lock cycle.\n        await taskModel.lockDependencyGraph();\n        // Cancel by the frozen id set rather than the pre-read topic list, so a\n        // topic that started between the snapshot and this transaction is still\n        // closed together with the status update.\n        canceledTopics = await taskTopicModel.cancelRunningByTaskIds(targetIds);''')
