case='''  describe('dependency lock ordering', () => {\n    it('acquires the graph lock before touching running topic rows in a cascade', async () => {\n      const order: string[] = [];\n      mockTaskModel.resolve.mockResolvedValue({ id: 'task-1', identifier: 'T-1', status: 'running' });\n      mockTaskModel.findAllDescendants.mockResolvedValue([]);\n      mockTaskModel.lockDependencyGraph.mockImplementation(async () => { order.push('graph'); });\n      mockTaskTopicModel.cancelRunningByTaskIds.mockImplementation(async () => { order.push('topics'); return []; });\n      mockTaskModel.updateStatusForIds.mockResolvedValue([{ id: 'task-1', status: 'paused' }]);\n      db.transaction = vi.fn(async (fn: any) => fn(db)) as any;\n      await new TaskService(db, userId).updateStatusCascade({ id: 'T-1', status: 'paused' });\n      expect(order.slice(0, 2)).toEqual(['graph', 'topics']);\n    });\n  });\n\n''';p.write_text(s.replace(marker,case+marker))
